import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`help-center-builder`,heroTitle:`Build your help center in minutes`,heroSubtitle:`Perplexity Computer reads your site, writes FAQs and support articles, and delivers a complete help center — automatically.`,inputUrlCta:`Build my help center`,inputUrlPlaceholder:`www.yoursite.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of all product pages, service pages, documentation, policies, pricing, and any existing support or FAQ content. Then build me a complete help center from scratch. 1) Create a category structure that organizes all support topics logically (e.g., Getting Started, Account & Billing, Features, Troubleshooting, Integrations). 2) Write 20–40 FAQ entries with clear, accurate answers based on the site's actual content. 3) Write step-by-step support articles for the top 10 user journeys you identify — onboarding, account setup, key feature walkthroughs, billing changes, and common troubleshooting flows. 4) Generate a set of 15–20 canned response templates for common support replies — password resets, refund requests, feature questions, bug reports, escalations. 5) Format everything so it's ready to paste into Intercom, Notion, or a CMS — use clean headings, numbered steps, and consistent formatting throughout. Deliver the full output organized by category with a table of contents at the top.`,heroOverlaySteps:[`Analyzing your site for product pages, docs, and policies`,`Writing FAQs and step-by-step support articles`,`Generating canned response templates for common tickets`,`Help center structured and formatted — ready to publish`],generatingSteps:[`Visiting {url} to extract product info, docs, policies, and existing support content`,`Designing an agent to write FAQs, support articles, and response templates from your site content`,`Configuring category structure and formatting for Intercom, Notion, or your CMS`,`Setting up your complete help center with 20–40 FAQs and step-by-step articles`],featureSectionTitle:`From website to help center`,featureCardTitles:[`Connects to your support stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Notion, Zendesk, Slack, Google Docs, Google Drive — Computer formats and delivers your help center content straight into the tools your team already uses.`,`Category structure. 20–40 FAQ entries with answers. Step-by-step support articles. Canned response templates. All formatted and ready to paste into your CMS.`],capabilitySectionTitle:`Your support writer, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a publish-ready help center.`,capabilityCards:[{title:`Site Analysis`,description:`Computer can analyze your entire site — product pages, docs, policies, pricing — and extract every detail your support content needs to cover.`},{title:`FAQ Generation`,description:`Computer can write 20–40 FAQ entries with accurate answers pulled directly from your site — organized by topic and ready to publish.`},{title:`Support Articles`,description:`Computer can identify your top user journeys and write step-by-step guides for onboarding, setup, troubleshooting, and key feature walkthroughs.`},{title:`Connect Your Tools`,description:`Computer can push content to Notion, Zendesk, Google Docs, Slack, and more — build workflows across your entire support and knowledge stack.`},{title:`Remember & Improve`,description:`Computer can remember your product details, tone, and past help center versions — so updates stay consistent and every revision builds on the last.`},{title:`Monitor & Refresh`,description:`Computer can re-analyze your site on schedule and flag when product changes mean your help center needs new articles or updated answers.`}]});export{t as default};
